-- Only DO_SKILL_CAST updates this state; a submitted request is not a cast.
function lastcast(skill)
    local me = GetClientPlayer()
    if not me or tLastCast.player ~= me.dwID then return false end
    local id = tonumber(skill) or GetPlayerSkillInfo(skill)
    return id ~= nil and id == tLastCast.skill
end

local function GetSkillCD(szText)
	local me = (MeCache and MeCache.Get and MeCache:Get()) or GetClientPlayer()
	local dwSkillID, dwLevel = GetPlayerSkillInfo(szText)
	if dwSkillID then
		if tSkillCastFrame and tSkillCastFrame[dwSkillID] then
			local nCur = (GetLogicFrameCount and GetLogicFrameCount()) or 0
			local nDebounce = ((dwSkillID == 189 or dwSkillID == 190) and 36) or 4
			local diff = nCur - tSkillCastFrame[dwSkillID]
			if diff >= 0 and diff < nDebounce then
				return (nDebounce - diff) / (GLOBAL and GLOBAL.GAME_FPS or 16)
			end
		end
		if me and me.GetSkillCDProgress then
			local ok, bCool, nLeft, nTotal = pcall(function() return me.GetSkillCDProgress(dwSkillID, dwLevel or 1) end)
			if ok and bCool then
				return (tonumber(nLeft) or 0) / (GLOBAL and GLOBAL.GAME_FPS or 16)
			end
		end
		return 0
	end
	local dwPetSkillID = GetPetSkill and GetPetSkill(szText)
	if dwPetSkillID then
		local nCur = (GetLogicFrameCount and GetLogicFrameCount()) or 0
		local last = tSkillCastFrame and tSkillCastFrame[dwPetSkillID]
		if last and nCur >= last then
			local elapsed = nCur - last
			local nTotalFrames = (dwPetSkillID == 2477) and 320 or 16
			if elapsed < nTotalFrames then
				return (nTotalFrames - elapsed) / GLOBAL.GAME_FPS
			end
		end
	end
	return 0
end


local function GetItemPos(szText)
	local me = GetClientPlayer()
	for dwBox = 1, 6 do
		local dwSize = me.GetBoxSize(dwBox)
		if dwSize > 0 then
			for dwX = 0, dwSize - 1 do
				local item = me.GetItem(dwBox, dwX)
				if item and item.szName == szText then
					return dwBox, dwX
				end
			end
		end
	end
	return nil
end


local function GetBagFreeBoxList()
	local me = GetClientPlayer()
	local tBoxTable = {}
	for nIndex = 6, 1, -1 do
		local dwBox = INVENTORY_INDEX.PACKAGE + nIndex - 1
		local dwSize = me.GetBoxSize(dwBox)
		if dwSize > 0 then
			for dwX = dwSize, 1, -1 do
				local item = me.GetItem(dwBox, dwX - 1)
				if not item then
					local i, j = dwBox, dwX - 1
					table.insert(tBoxTable, {i, j})
				end
			end
		end
	end
	return tBoxTable
end

