local function GetSmartTargetXYZ()
	local me = (MeCache and MeCache.Get and MeCache:Get()) or (GetClientPlayer and GetClientPlayer())
	if not me then return nil, nil, nil end
	local tar = (GetCurrentTargetObject and GetCurrentTargetObject()) or (TarCache and TarCache.Get and TarCache:Get())
	if not tar and me.GetTarget then
		local ok, dwType, dwID = pcall(function() return me.GetTarget() end)
		if ok and dwID and dwID > 0 then
			tar = (GetTargetHandle and GetTargetHandle(dwType, dwID)) or (GetNpc and GetNpc(dwID)) or (GetPlayer and GetPlayer(dwID))
		end
	end
	if tar and tar.nCurrentLife and tar.nCurrentLife <= 0 then
		tar = nil
	end
	if tar and tar.nX and tar.nY and tar.nZ then
		return tar.nX, tar.nY, tar.nZ
	end
	if me.nX and me.nY and me.nZ then
		return me.nX, me.nY, me.nZ
	end
	return nil, nil, nil
end
_G.GetSmartTargetXYZ = GetSmartTargetXYZ

local function GetMouseTargetXYZ()
	local me = (MeCache and MeCache.Get and MeCache:Get()) or (GetClientPlayer and GetClientPlayer())
	local cx, cy = nil, nil
	if Cursor and Cursor.GetPos then
		local ok, x, y = pcall(Cursor.GetPos)
		if ok and x and y then cx, cy = x, y end
	end
	if not cx or not cy then
		if GetCursorPos then
			local ok, x, y = pcall(GetCursorPos)
			if ok and x and y then cx, cy = x, y end
		end
	end
	if cx and cy then
		if AIO and type(AIO.GetScreenPoint) == "function" then
			local ok, wx, wy, wz = pcall(AIO.GetScreenPoint, cx, cy)
			if ok and wx and wy and wz then
				return wx, wy, wz
			end
		end
		if Scene and type(Scene.ScreenToWorld) == "function" then
			local ok, wx, wy, wz = pcall(Scene.ScreenToWorld, cx, cy)
			if ok and wx and wy and wz then
				return wx, wy, wz
			end
		end
	end
	local tx, ty, tz = GetSmartTargetXYZ()
	if tx and ty and tz then
		return tx, ty, tz
	end
	if me and me.nX and me.nY and me.nZ then
		return me.nX, me.nY, me.nZ
	end
	return nil, nil, nil
end
_G.GetMouseTargetXYZ = GetMouseTargetXYZ

local function SyncAIOTLHelperBachTuc()
	local mode = (xMacro and xMacro.GroundTargetMode) or "target"
	if AIO_TLHelper then
		local tlMode = 3
		if mode == "mouse" then
			tlMode = 2
		elseif mode == "manual" then
			tlMode = 0
		end
		if type(AIO_TLHelper.tTrapList) == "table" then
			AIO_TLHelper.tTrapList[2212] = tlMode
			AIO_TLHelper.tTrapList[2492] = tlMode
			AIO_TLHelper.tTrapList[2496] = tlMode
			AIO_TLHelper.tTrapList[5764] = tlMode
		end
		if type(AIO_TLHelper.tTrapMode) == "table" then
			AIO_TLHelper.tTrapMode[2212] = tlMode
			AIO_TLHelper.tTrapMode[2492] = tlMode
			AIO_TLHelper.tTrapMode[2496] = tlMode
			AIO_TLHelper.tTrapMode[5764] = tlMode
		end
		if tlMode > 0 then
			AIO_TLHelper.bAutoTrap = true
		end
	end
end
_G.SyncAIOTLHelperBachTuc = SyncAIOTLHelperBachTuc

local function PrepareGroundSkillOnTarget(dwSkillID)
	local nID = tonumber(dwSkillID)
	if not nID or (not tCombatGroundSkills[nID] and not tGroundTargetSkill[nID] and nID ~= 2212) then
		return
	end
	local mode = (xMacro and xMacro.GroundTargetMode) or "target"
	SyncAIOTLHelperBachTuc()
	if mode == "manual" then
		_lastGroundSkillID = nil
		_lastGroundSkillTime = 0
		return
	end
	local now = (GetTime and GetTime()) or 0
	_lastGroundSkillID = nID
	_lastGroundSkillTime = now
	if AIO_TLHelper and type(AIO_TLHelper.ForcePlace) == "function" then
		local tlMode = (mode == "mouse") and 2 or 3
		pcall(AIO_TLHelper.ForcePlace, nID, tlMode)
	end
end
