local function GetCurrentGroundSkillID(...)
	for i = 1, select("#", ...) do
		local v = select(i, ...)
		if type(v) == "number" and (tCombatGroundSkills[v] or tGroundTargetSkill[v] or v == 2212) then
			return v
		elseif type(v) == "table" or type(v) == "userdata" then
			if v.GetObjectData then
				local ok, id = pcall(v.GetObjectData, v)
				if ok and type(id) == "number" and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
					return id
				end
			end
			for _, k in ipairs({"dwSkillID", "dwID", "nSkillID", "dwSkill", "nID"}) do
				local id = tonumber(v[k])
				if id and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
					return id
				end
			end
		end
	end
	if this and (type(this) == "table" or type(this) == "userdata") then
		if this.GetObjectData then
			local ok, id = pcall(this.GetObjectData, this)
			if ok and type(id) == "number" and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
				return id
			end
		end
		for _, k in ipairs({"dwSkillID", "dwID", "nSkillID", "dwSkill", "nID"}) do
			local id = tonumber(this[k])
			if id and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
				return id
			end
		end
	end
	local now = (GetTime and GetTime()) or 0
	if _lastGroundSkillID and (now >= _lastGroundSkillTime) and (now - _lastGroundSkillTime <= 2000) then
		return _lastGroundSkillID
	end
	return nil
end

local function MakeSelectPointInterceptor(origFn)
	return function(fnCallback, ...)
		local mode = (xMacro and xMacro.GroundTargetMode) or "target"
		local skillID = GetCurrentGroundSkillID(...)
		-- TUYET DOI KHONG can thiep vao vat pham lam nhiem vu hoac thao tac chon vung ngoai ky nang!
		if not skillID or mode == "manual" then
			_lastGroundSkillID = nil
			_lastGroundSkillTime = 0
			if origFn then
				return origFn(fnCallback, ...)
			end
			return
		end

		-- Day la ky nang chien dau dat vung (Bach Tuc 2212, v.v.)
		_lastGroundSkillID = nil
		_lastGroundSkillTime = 0

		local x, y, z
		if mode == "mouse" then
			x, y, z = GetMouseTargetXYZ()
		else
			x, y, z = GetSmartTargetXYZ()
		end

		if x and y and z then
			-- 1. Uu tien goi callback truc tiep neu engine truyen vao
			if type(fnCallback) == "function" then
				local ok = pcall(fnCallback, x, y, z)
				if ok then
					return
				end
			end
			-- 2. Mo vung bang origFn roi snap ngay lap tuc bang DoSelectPoint (nhu HM)
			if origFn then
				pcall(origFn, fnCallback, ...)
			end
			if UserSelect and UserSelect.DoSelectPoint then
				pcall(UserSelect.DoSelectPoint, x, y, z)
			end
			return
		end

		if origFn then
			return origFn(fnCallback, ...)
		end
	end
end

local function MakeSkillUseInterceptor(origFn)
	return function(dwSkillID, dwLevel, ...)
		local nID = tonumber(dwSkillID)
		if nID and (nID == 2212 or tCombatGroundSkills[nID] or tGroundTargetSkill[nID]) then
			PrepareGroundSkillOnTarget(nID)
		end
		if origFn then
			return origFn(dwSkillID, dwLevel, ...)
		end
	end
end

local function HookUserSelectPoint()
	SyncAIOTLHelperBachTuc()
	local tSlots = {
		{ tbl = UserSelect, name = "SelectPoint", key = "UserSelect.SelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = UserSelect, name = "SelectArea", key = "UserSelect.SelectArea", maker = MakeSelectPointInterceptor },
		{ tbl = _G, name = "SelectPoint", key = "_G.SelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = _G, name = "UserSelectPoint", key = "_G.UserSelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = _G, name = "OnUseSkill", key = "_G.OnUseSkill", maker = MakeSkillUseInterceptor },
		{ tbl = _G, name = "OnCastPlayerSkill", key = "_G.OnCastPlayerSkill", maker = MakeSkillUseInterceptor },
		{ tbl = _G, name = "OnAddOnUseSkill", key = "_G.OnAddOnUseSkill", maker = MakeSkillUseInterceptor },
	}
	for _, s in ipairs(tSlots) do
		local tbl = s.tbl
		if type(tbl) == "table" and type(tbl[s.name]) == "function" then
			local curFn = tbl[s.name]
			if not _tXMacroWrapped[s.key] or curFn == _tXMacroOrig[s.key] then
				_tXMacroOrig[s.key] = curFn
				local wrapped = s.maker(curFn)
				_tXMacroWrapped[s.key] = wrapped
				pcall(function() tbl[s.name] = wrapped end)
			end
		end
	end
end
HookUserSelectPoint()

local function OnCastPlayerSkill(me, dwSkillID, dwLevel)
	if not (me and me.GetOTActionState and me.GetOTActionState() == 2 and bProtectChannelSkill) then
		local nCur = (GetLogicFrameCount and GetLogicFrameCount()) or 0
		if tSkillCastFrame then
			tSkillCastFrame[dwSkillID] = nCur
		end
		PrepareGroundSkillOnTarget(dwSkillID)
		OnAddOnUseSkill(dwSkillID, dwLevel)
		if tGroundTargetSkill[dwSkillID] or dwSkillID == 2212 or (tCombatGroundSkills and tCombatGroundSkills[dwSkillID]) then
			DoSmartSelectPoint()
		end
		local now = (GetTime and GetTime()) or 0
		local skill = (GetSkill and GetSkill(dwSkillID, dwLevel)) or nil
		local bIsChan = (skill and skill.bIsChannelSkill) or tChannelSkill[dwSkillID]
		local bIsGround = (tGroundTargetSkill and tGroundTargetSkill[dwSkillID]) or dwSkillID == 2212 or (tCombatGroundSkills and tCombatGroundSkills[dwSkillID])
		if now > 0 and not tOffGCDSkill[dwSkillID] then
			local nLock = bIsGround and 650 or (bIsChan and 500 or 260)
			if now + nLock > nGlobalCastLockUntil then
				nGlobalCastLockUntil = now + nLock
			end
		end
		local szName = (Table_GetSkillName and Table_GetSkillName(dwSkillID, dwLevel)) or tostring(dwSkillID)
		if XMCore_Sys then
			XMCore_Sys("[xMacro] -> " .. tostring(szName))
		end
		if bIsChan and bProtectChannelSkill then
			return false
		end
		return true
	end
	return true
end


